/* From Uiverse.io by htwarriors108 - Tags: gradient, button, animated, colorful, hover effect, click effect, click animation, box-shadow, multicolor */
.__UIV_SCOPE__ .button {
  height: 50px;
  width: 180px;
  background: linear-gradient(135deg, #14ffe9, #ffeb3b, #ff00e0);
  border-radius: 25px;
  animation: animate 1.5s linear infinite;
  border: none;
  cursor: pointer;
}

.__UIV_SCOPE__ .button, .__UIV_SCOPE__ .display, .__UIV_SCOPE__ #msg {
  transition: 0.3s;
}

.__UIV_SCOPE__ .button:active .display {
  background: rgba(255, 255, 255, 0.5);
}

.__UIV_SCOPE__ .button:active .display #msg {
  -webkit-text-fill-color: #1b1b1b;
}

.__UIV_SCOPE__ .button:hover {
  scale: 1.15;
  animation: animate 0.7s linear infinite;
  transform: translateY(-15px);
}

.__UIV_SCOPE__ .button .display, .__UIV_SCOPE__ .button span {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.__UIV_SCOPE__ .button .display {
  z-index: 1;
  background-color: #1b1b1b;
  height: 42.5px;
  width: 172.5px;
  border-radius: 20px;
  text-align: center;
}

.__UIV_SCOPE__ .button .display #msg {
  line-height: 42.5px;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: 3px;
  background: linear-gradient(135deg, #14ffe9, #ffeb3b, #ff00e0);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

@keyframes animate {
  100% {
    filter: hue-rotate(360deg);
  }
}

.__UIV_SCOPE__ .button span {
  height: 100%;
  width: 100%;
  background: inherit;
  border-radius: 25px;
}

.__UIV_SCOPE__ .button span:first-child {
  filter: blur(15px);
}

.__UIV_SCOPE__ .button span:last-child {
  filter: blur(15px);
  transition: 0.3s;
}

.__UIV_SCOPE__ .button:hover span:last-child {
  width: 110%;
  height: 120%;
}
